from taf.internal.robot_typecasts import time_to_seconds








class EthernetServiceOamInterface(object):
    def start_service_oam_loopback(self, oam_ma_dn, ccm_remote_mac_addr, ccm_remote_mep_id, timeout=60):
        """Start service OAM loopback.

        :param string oam_ma_dn: oam_ma distname.
        :param string ccm_remote_mac_addr: ccm_remote mac address.
        :param integer ccm_remote_mep_id: ccm_remote_mep_id
        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: result of Loopback test
        """

        timeout = time_to_seconds(timeout)
        str(oam_ma_dn)
        str(ccm_remote_mac_addr)
        ccm_remote_mep_id = int(ccm_remote_mep_id)
        parameters = {
            "oamMaDN": oam_ma_dn,
            "ccmRemoteMacAddr": ccm_remote_mac_addr,
            "ccmRemoteMepId": ccm_remote_mep_id

        }
        return self._api_client.execute_procedure("startServiceOamLoopback", parameters, timeout)

    def start_service_oam_link_trace(self, oam_ma_dn, ccm_remote_mac_addr, ccm_remote_mep_id, timeout=60):
        """Start service OAM link trace.

        :param string oam_ma_dn: oam_ma distname.
        :param string ccm_remote_mac_addr: ccm_remote mac address.
        :param integer ccm_remote_mep_id: ccm_remote_mep_id
        :param float timeout: Time to wait for positive procedure result.
        

        :rtype: dict
        :return: result of Linktrace test
        """

        timeout = time_to_seconds(timeout)
        str(oam_ma_dn)
        str(ccm_remote_mac_addr)
        ccm_remote_mep_id = int(ccm_remote_mep_id)
        parameters = {
            "oamMaDN": oam_ma_dn,
            "ccmRemoteMacAddr": ccm_remote_mac_addr,
            "ccmRemoteMepId": ccm_remote_mep_id

        }
        return self._api_client.execute_procedure("startServiceOamLinkTrace", parameters, timeout)
